module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

reg [9:0] accumulator;
reg [1:0] counter;
reg valid_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accumulator <= 10'd0;
        counter <= 2'd0;
        valid_out_reg <= 1'b0;
    end else begin
        if (valid_in == 1'b1) begin
            if (counter < 2'd3) begin
                accumulator <= accumulator + {2'b00, data_in}; 
                counter <= counter + 2'd1;
                valid_out_reg <= 1'b0; 
            end else begin
                accumulator <= accumulator + {2'b00, data_in}; 
                counter <= 2'd0; 
                valid_out_reg <= 1'b1; 
            end
        end else begin
            valid_out_reg <= 1'b0; 
        end
    end
end

assign data_out = accumulator;
assign valid_out = valid_out_reg;
endmodule
